$ErrorActionPreference = "Stop"

$ROOT = "C:\Users\santi\OneDrive\Escritorio\ALPHA_ENGINE_PRODUCTION"
$REC  = Join-Path $ROOT "ALPHA_ENGINE_DATA_RECOVERY_V1"
$V13  = Join-Path $ROOT "ALPHA_ENGINE_V13_RETURN_FIRST_MULTI_HORIZON"
$BUILDER = Join-Path $REC "scripts\build_forward_nav_v42.py"
$SMOKE   = Join-Path $REC "scripts\smoke_v42.py"
$START   = Join-Path $ROOT "START_ALPHA_ENGINE_V4.ps1"

Write-Host ""
Write-Host "================================================================"
Write-Host "ALPHA ENGINE V4.2 - RESUME FIX1"
Write-Host "FIX: EXACT HOLDOUT CALENDAR FOR FORWARD NAV PARITY"
Write-Host "RESUME FROM FAILED STEP 4 ONLY"
Write-Host "NO REINSTALL / NO SHEETS / NO LLM / NO SEALED V13 MUTATION"
Write-Host "================================================================"

foreach($p in @($ROOT,$REC,$V13,$BUILDER,$SMOKE,$START)) {
    if(-not(Test-Path $p)){throw "Missing required path: $p"}
}

Write-Host ""
Write-Host "[1/7] SEALED V13 IMMUTABILITY SNAPSHOT"
$critical=@(
  "outputs\v13_phase2r_model_spec.json",
  "outputs\v13_phase2u_expert_evidence.csv",
  "outputs\v13_phase3aa_freeze_manifest.json",
  "outputs\v13_phase4_sealed_features.csv",
  "outputs\v13_phase4_model_seal_manifest.json",
  "outputs\v13_phase4_sealed_model_bundle.joblib"
)
$before=@{}
foreach($rel in $critical){
    $p=Join-Path $V13 $rel
    if(-not(Test-Path $p)){throw "Critical V13 file missing: $p"}
    $before[$rel]=(Get-FileHash -Algorithm SHA256 $p).Hash
}
Write-Host "  PASS 6/6"

Write-Host ""
Write-Host "[2/7] PATCH FORWARD NAV BUILDER ONLY"
$backup="$BUILDER.before_fix1_$(Get-Date -Format yyyyMMdd_HHmmss)"
Copy-Item $BUILDER $backup -Force
[IO.File]::WriteAllBytes($BUILDER,[Convert]::FromBase64String(""))
python -c "from pathlib import Path; p=Path(r'$BUILDER'); compile(p.read_text(encoding='utf-8'),str(p),'exec'); print('  syntax PASS')"
if($LASTEXITCODE -ne 0){throw "Patched forward builder syntax failed"}
Write-Host "  backup: $backup"
Write-Host "  PASS"

Write-Host ""
Write-Host "[3/7] REBUILD CAUSAL FORWARD NAV"
Set-Location $ROOT
python $BUILDER
if($LASTEXITCODE -ne 0){
    throw "Forward NAV still failed a blocking audit. V13 sealed core remains untouched."
}
Write-Host "  PASS"

Write-Host ""
Write-Host "[4/7] RESTART INSTALLED V4.2"
$listeners=@(Get-NetTCPConnection -LocalPort 8765 -State Listen -ErrorAction SilentlyContinue)
foreach($l in $listeners){
    $proc=Get-CimInstance Win32_Process -Filter "ProcessId=$($l.OwningProcess)" -ErrorAction SilentlyContinue
    if($proc -and [string]$proc.CommandLine -like "*run_alpha_engine_v4.py*"){
        Stop-Process -Id $l.OwningProcess -Force
        Write-Host "  stopped Alpha PID=$($l.OwningProcess)"
    } else {
        throw "Port 8765 occupied by non-Alpha process. Nothing killed."
    }
}
Start-Sleep -Milliseconds 800
$launcher=Start-Process -FilePath "powershell.exe" -ArgumentList @(
    "-NoProfile","-ExecutionPolicy","Bypass","-File",$START
) -WindowStyle Hidden -PassThru
Write-Host "  launcher PID=$($launcher.Id)"

$ready=$false
for($i=0;$i -lt 50;$i++){
    Start-Sleep -Milliseconds 750
    try{
        $h=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/health" -TimeoutSec 5
        if($h.status -eq "PASS" -and $h.version -eq "V4.2"){$ready=$true;break}
    }catch{}
}
if(-not $ready){throw "V4.2 server did not become ready"}
Write-Host "  PASS"

Write-Host ""
Write-Host "[5/7] CATCH UP MARKET + FORWARD TO LATEST COMPLETED SESSION"
$mr=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/market/refresh" -Method Post -ContentType "application/json" -Body "{}" -TimeoutSec 700
if($mr.status -notin @("PASS","BUSY")){throw "Market refresh failed: $($mr.status)"}
Write-Host "  market: $($mr.status)"

$fj=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/forward/job" -TimeoutSec 40
if($fj.stale -eq $true -and $fj.status -ne "RUNNING"){
    $kick=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/forward/refresh" -Method Post -ContentType "application/json" -Body "{}" -TimeoutSec 40
    Write-Host "  forward start: $($kick.status)"
}

$forwardReady=$false
for($i=0;$i -lt 240;$i++){
    Start-Sleep -Seconds 5
    $fj=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/forward/job" -TimeoutSec 40
    if($fj.status -eq "FAIL"){
        throw "Forward catch-up failed: $($fj.error)"
    }
    if($fj.stale -eq $false -and $fj.status -ne "RUNNING"){
        $fn=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/forward/nav" -TimeoutSec 40
        if($fn.status -eq "PASS" -and $fn.latest_date -eq $fj.current_model_session){
            $forwardReady=$true
            break
        }
    }
    if(($i % 12) -eq 0){
        Write-Host "  waiting... status=$($fj.status) model=$($fj.current_model_session) market=$($fj.latest_completed_market_session) stale=$($fj.stale)"
    }
}
if(-not $forwardReady){throw "Forward catch-up timeout after 20 minutes"}
Write-Host "  forward model: $($fj.current_model_session)"
Write-Host "  market session: $($fj.latest_completed_market_session)"
Write-Host "  stale: $($fj.stale)"
Write-Host "  PASS"

Write-Host ""
Write-Host "[6/7] FULL V4.2 PRODUCT SMOKE"
python $SMOKE
if($LASTEXITCODE -ne 0){throw "V4.2 smoke failed. V13 sealed core remains untouched."}
Write-Host "  PASS"

Write-Host ""
Write-Host "[7/7] SEALED V13 IMMUTABILITY VERIFY"
foreach($rel in $critical){
    $p=Join-Path $V13 $rel
    $after=(Get-FileHash -Algorithm SHA256 $p).Hash
    if($after -ne $before[$rel]){throw "SEALED V13 MUTATION DETECTED: $rel"}
}
Write-Host "  PASS 6/6 byte-identical"

$fn=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/forward/nav" -TimeoutSec 40
$rec=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/recommendations" -TimeoutSec 90
$mj=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/market/job" -TimeoutSec 40

Write-Host ""
Write-Host "================================================================"
Write-Host "ALPHA ENGINE V4.2 FIX1: PASS"
Write-Host "================================================================"
Write-Host "MARKET AUTO        : $($mj.refresh_every_seconds)s / REGULAR ONLY"
Write-Host "FORWARD MODEL      : $($fj.current_model_session)"
Write-Host "FORWARD NAV        : $($fn.start_date) -> $($fn.latest_date)"
Write-Host "HOLDOUT PARITY     : $($fn.holdout_parity.status)"
Write-Host "RECOMMENDATIONS    : $($rec.portfolio_status)"
Write-Host "REAL ORDERS        : NO"
Write-Host "LLM                : PAUSED"
Write-Host "V13 SEALED CORE    : UNCHANGED"
Write-Host "================================================================"

Start-Process "http://127.0.0.1:8765/"
